mapper.select:
SELECT

FROM inventory_release_tasks
WHERE (
        status IN ('PENDING', 'RETRY')
        AND next_retry_at <= #{now}
      )
   OR (
        status = 'PROCESSING'
        AND locked_at <= #{lockExpiredBefore}
      )
ORDER BY next_retry_at ASC
LIMIT #{limit}

mapper.update:
UPDATE inventory_release_tasks
SET status = 'PROCESSING',
    locked_at = #{now},
    updated_at = #{now}
WHERE id = #{taskId}
  AND (
        (status IN ('PENDING', 'RETRY') AND next_retry_at <= #{now})
        OR (status = 'PROCESSING' AND locked_at <= #{lockExpiredBefore})
      )
